// CVar System
//
// A CVar is a named, typed, atomic variable readable/writable from any thread without locks. INT CVars use _Atomic int; FLOAT CVars pack
// into _Atomic uint via memcpy (type-punning). No string CVars - use a separate localization database for text.
//
// Task-safe console variables. Each CVar is a protected object with atomic Get/Set entries. The Edit_State tracks when and how each CVar
// was last modified (timestamp + source).
//
// All CVar values are C11 atomics - no mutexes, no locks, no contention. INT CVars use _Atomic int directly. FLOAT CVars store their bits
// in _Atomic int via Float_To_Bits / Bits_To_Float (memcpy-based type-punning, avoids strict aliasing violations).
//
// Registration happens single-threaded at startup, so CVar_Count is not atomic. Get/Set are lock-free and safe from any thread at any time.
//
#define CVAR_NONE     0
#define CVAR_ARCHIVE  1 // Save to and load from config file
#define CVAR_READONLY 2 // Cannot be changed from console; engine-internal only
#define CVAR_LATCH    4 // Change is deferred until next map load / restart
#define CVAR_CHEAT    8 // Only active when cheats are enabled
typedef enum {CVAR_INT, CVAR_FLOAT} CVar_Type;

typedef struct {
  _Atomic uint64_t Time_Stamp;         // The SDL_GetPerformanceCounter ticks at last Set
  _Atomic int      Edited_Via_Command; // Value of 1 if the last Set came from console Submit, 0 if from code
} CVar_Edit_State;

typedef struct {
  const char     *Name;           // For example: "r_width", "w_gravity", "in_sensitivity", etc.
  const char     *Help;           // One-line description for console / config comments
  CVar_Type       Type;           // INT or FLOAT
  int             Flags;          // Bitmask of CVAR_ARCHIVE | CVAR_READONLY | ...
  _Atomic int     Value_I;        // Current value (int CVar) - lock-free atomic
  _Atomic int     Value_F_Bits;   // Current value (float CVar) - float bits stored as atomic int
  int             Default_I;      // Default value for int CVars
  int             Default_F_Bits; // Default value bits for float CVars
  float           Min, Max;       // Numeric clamp range
  _Atomic int     Modified;       // Dirty flag - set on write, cleared by consumer (atomic exchange)
  CVar_Edit_State Last_Edit;      // When and how the CVar was last modified
} CVar;

