// Phyx motion modes — each mode maps to a simple, well-understood solver primitive. Named after the SIGGRAPH lineage: PBD (Müller 2007),
// XPBD (Macklin 2016), shape matching (Müller 2005).
//
//   PHYX_STATIC     — Infinite mass, never moves. Participates in collision only.
//   PHYX_DYNAMIC    — Verlet point mass: gravity + collision + restitution. The "hello world" of physics.
//   PHYX_KINEMATIC  — Scripted path (linear lerp between Origin and Target). Zero-cost animation.
//   PHYX_BALLISTIC  — Projectile arc: initial velocity + gravity, no drag. Clean parabola.
//   PHYX_PENDULUM   — Single-constraint PBD: pivot + distance constraint. Classic SIGGRAPH demo.
//   PHYX_SPRING     — Damped spring (Hooke's law): anchor + rest length + stiffness + damping.
//   PHYX_BUOYANT    — Simple buoyancy: submerged fraction * displaced water weight. Archimedes easy win.
//
typedef enum {
  PHYX_STATIC    = 0, // Immovable collider
  PHYX_DYNAMIC   = 1, // Gravity + Verlet integration + bounce
  PHYX_KINEMATIC = 2, // Scripted linear path (Origin > Target)
  PHYX_BALLISTIC = 3, // Parabolic arc (initial velocity + gravity, no drag)
  PHYX_PENDULUM  = 4, // PBD distance constraint from pivot (single-point pendulum)
  PHYX_SPRING    = 5, // Damped Hooke's law spring (anchor + rest_length + k + c)
  PHYX_BUOYANT   = 6, // Archimedes buoyancy (water plane + displaced volume)
  PHYX_MODE_COUNT
} Phyx_Mode;

// Common entity attributes
typedef struct {

  // Identity / linkage
  char Name    [64]; // Graph node name (e.g. "targetname")
  char Target  [64]; // Primary target id
  char Target2 [64]; // Secondary target id
  char Parent  [64]; // Parent attachment id

  // Transform
  vec3  Origin; // World-space position
  vec3  Angles; // Pitch/Yaw/Roll degrees
  float Scale;  // Uniform scale

  // Bounds for volumes and brush entities
  vec3  Mins;   // Local or world mins
  vec3  Maxs;   // Local or world maxs
  float Radius; // Radius for spherical volumes
  float Height; // Height for cylindrical volumes

  // Rendering assets
  char Model    [96];  // Model path 
  char Material [96];  // Material/shader path
  char Sound    [96];  // Sound file path
  char Script   [96];  // Script path
  char Message  [128]; // UI/message string
  vec3 Color;          // Range RGB (0..1) where applicable
  float Alpha;         // Opacity (1.0 default)

  // Gameplay and physics
  int   Spawnflags; // Generic spawnflags bitfield
  int   Flags;      // Generic runtime flags 
  int   Team;       // Team or faction id
  int   Health;     // Hit points
  int   Armor;      // Armor points 
  int   Damage;     // Damage (for hurt/explosive/etc)
  int   Count;      // Generic count 
  float Speed;      // Generic speed 
  float Wait;       // Seconds
  float Delay;      // Seconds
  float Random;     // Random variance (seconds or scalar)
  float Accel;    
  float Decel;  
} Entity_Common;

// BSP Entity discriminate union
typedef struct {
  Entity_Kind   Kind;   // Discriminant tag
  Entity_Common Common; // Shared attributes 
  union { // case Kind is

    // when ENTITY_WORLD =>
    struct {
      float Gravity;       // World gravity scalar 
      float Time_Limit;    // Match time limit 
      int   Score_Limit;   // Score limit 
      float Ambient_Light; // Scalar ambient floor
    } world;

    // when ENTITY_INFO_PLAYER_ =>
    struct {
      int   Player_Class;  // Class index 
      int   Loadout;       // Loadout id 
      float Fov;           // Suggested FOV 
      float View_Height;   // Standing view height 
      float Crouch_Height; // Crouch view height 
    } player;

    // when ENTITY_LIGHT | ENTITY_LIGHT_SPOT =>
    struct {
      float Intensity;    // Luminous intensity / radius scalar
      float Range;        // Explicit range 
      float Inner_Angle;  // Spot inner cone degrees 
      float Outer_Angle;  // Spot outer cone degrees 
      int   Cast_Shadows; // Non-zero = shadow caster
      float Falloff;      // When 1 = linear, 2 = quadratic, etc
    } light;

    // when ENTITY_SOUND_EMITTER =>
    struct {
      float Volume;       // Range 0..1
      float Pitch;        // When 1 = normal
      float Min_Distance; // Full volume within this distance
      float Max_Distance; // Silence beyond this distance
      int   Looping;      // Non-zero = loop
    } sound;

    // when ENTITY_DECAL =>
    struct {
      float Size_X, Size_Y; // Projected size
      float Rotation;       // Degrees
      float Fade_Time;      // Seconds until fully faded: (0 = never)
    } decal;

    // when ENTITY_PARTICLE_SYSTEM =>
    struct {
      float Rate;     // Particles per second
      float Lifetime; // Seconds
      float Spread;   // Cone spread scalar
      float Velocity; // Initial speed scalar
    } particle;

    // when ENTITY_TRIGGER* =>
    struct {
      int Enabled;      // Non-zero = active
      int Filter_Team;  // When 0 = any, else team id
      int Filter_Class; // When 0 = any, else class id
      int Fire_Count;   // How many times it can fire: (0 = infinite)
    } trigger;

    // when ENTITY_TRIGGER_TELEPORT =>
    struct {
      int Preserve_Velocity; // Non-zero - keep incoming velocity
    } teleport;

    // when ENTITY_TRIGGER_PUSH =>
    struct {
      vec3  Push_Dir;   // Direction
      float Push_Speed; // Magnitude
    } push;

    // when movers/doors/platform/train =>
    struct {
      vec3  Move_Dir;    // Movement direction
      float Lip;         // Remaining overlap at end of travel
      float Distance;    // Travel distance 
      float Open_Angle;  // For rotating doors
      int   Toggle;      // Non-zero toggles behavior
      int   Starts_Open; // Non-zero to capture initial state
    } mover;

    // when ENTITY_BREAKABLE | ENTITY_EXPLOSIVE =>
    struct {
      float Explosion_Radius; // Blast radius
      float Explosion_Force;  // Impulse scalar
      int   Gib_Count;        // Debris count
    } breakable;

    // when ENTITY_ITEM_ =>
    struct {
      Weapon_Kind  Weapon;   // For ENTITY_ITEM_WEAPON
      Ammo_Kind    Ammo;     // For ENTITY_ITEM_AMMO
      Powerup_Kind Powerup;  // For ENTITY_ITEM_POWERUP
      int          Key_Id;   // For ENTITY_ITEM_KEY
      int          Respawn;  // Respawn seconds 
      float        Duration; // Powerup duration seconds 
    } item;

    // when ENTITY_PROJECTILE_SPAWNER =>
    struct {
      float Fire_Rate;        // Shots per second
      float Projectile_Speed; // Speed scalar
      float Spread;           // Spread scalar
      int   Burst;            // Shots per burst
    } projectile_spawner;

    // when ENTITY_TURRET =>
    struct {
      float Yaw_Rate;         // Degrees/sec
      float Pitch_Rate;       // Degrees/sec
      float Yaw_Min, Yaw_Max; // Limits
      float Pitch_Min, Pitch_Max;
      Weapon_Kind Weapon;
    } turret;

    // when ENTITY_VEHICLE =>
    struct {
      float Mass;         // Kg scalar
      float Engine_Power; // Generic power scalar
      float Turn_Rate;    // Degrees/sec
      int   Seats;        // Seat count
    } vehicle;

    // when ENTITY_NPC =>
    struct {
      int   Npc_Class;    // Class index
      float Aggro_Radius; // Detection range
      float Walk_Speed;   // Units/sec
      float Run_Speed;    // Units/sec
    } npc;

    // when ENTITY_OBJECTIVE =>
    struct {
      Objective_Kind Obj_Kind;
      int   Required_Count; // Objective count (e.g. collect N items)
      float Hold_Time;      // Hold/capture seconds
      int   Obj_Team;       // Owning team (0 = neutral)
    } objective;

    // when ENTITY_LOGIC_* =>
    struct {
      int   Value_A;
      int   Value_B;
      int   Threshold;
      float Interval;
      float Chance; // Range 0..1
    } logic;

    // when ENTITY_ENV_SKY =>
    struct {
      vec3 Direction; // Sun direction (normalized)
      vec3 Color;     // Sun color (linear 0..1)
      vec3 Ambient;   // Ambient color (linear 0..1)
    } env;

    // when ENTITY_PHYX =>
    struct {
      Phyx_Mode Mode;          // Physics motion mode (see Phyx_Mode enum)
      float     Mass;          // Mass in kg (0 = infinite for PHYX_STATIC)
      float     Restitution;   // Bounce coefficient (0..1, 0.5 = half energy)
      float     Friction;      // Surface friction coefficient
      vec3      Velocity;      // Initial velocity (PHYX_DYNAMIC, PHYX_BALLISTIC)
      vec3      Anchor;        // Pivot/anchor point (PHYX_PENDULUM, PHYX_SPRING)
      float     Rest_Length;   // Rest length for spring/pendulum constraint
      float     Stiffness;     // Spring constant k (PHYX_SPRING, N/m)
      float     Damping;       // Damping coefficient c (PHYX_SPRING, Ns/m)
      float     Water_Level;   // Y coordinate of water surface (PHYX_BUOYANT)
      float     Displaced_Vol; // Displaced volume m³ for buoyancy (PHYX_BUOYANT)
    } phyx;
  };
} BSP_Entity;

// Interleaved vertex layout matching the GPU shader input
typedef struct {
  vec3  Position;                        // World-space XYZ position
  float Padding_A;                       // Padding aligns to 16 bytes
  float Texture_UV [2], Lightmap_UV [2]; // Diffuse texture coordinates and lightmap atlas coordinates
  vec3  Normal;                          // Surface normal
  float Padding_B;                       // Padding aligns to 16 bytes
} Vertex;

// ── Material system: dual Classic/PBR workflow ───────────────────────────────────────────────────────────────────────────────────────────
typedef enum {
  MATERIAL_WORKFLOW_CLASSIC = 0,   // diffuse + spec/env + gloss (Q3/Source)
  MATERIAL_WORKFLOW_PBR     = 1    // baseColor + normal + roughness + metallic + ao + emissive (glTF)
} Material_Workflow;

#define MATERIAL_FLAG_NORMAL_FLIP_Y  (1u << 0)
#define MATERIAL_FLAG_ALPHA_TEST     (1u << 1)
#define MATERIAL_FLAG_TWO_SIDED      (1u << 2)
#define MATERIAL_FLAG_UNLIT          (1u << 3)
#define MATERIAL_FLAG_LIGHTMAPPED    (1u << 4)
#define MATERIAL_FLAG_EMISSIVE       (1u << 5)

// 144-byte GPU material struct — std430-friendly, mirrors GLSL layout exactly
typedef struct {
  uint Workflow;                 // Material_Workflow enum
  uint Flags;                    // MATERIAL_FLAG_* bitmask
  uint Base_Tex;                 // diffuse (classic) or baseColor (PBR);  0xFFFFFFFF = absent
  uint Normal_Tex;               // normal map
  uint Spec_Tex;                 // classic: specular color map
  uint Gloss_Tex;                // classic: gloss/shininess map
  uint EnvMask_Tex;              // classic: environment mask
  uint Rough_Tex;                // PBR: roughness map
  uint Metal_Tex;                // PBR: metallic map
  uint AO_Tex;                   // PBR: ambient occlusion
  uint Emissive_Tex;             // emissive map (both workflows)
  uint _pad0;                    // align to 16 bytes
  vec4 Base_Factor;              // rgb factor + alpha
  vec4 Spec_Factor;              // rgb spec color + gloss scale in .w
  vec4 PBR_Factor;               // x=roughness, y=metallic, z=ao_strength, w=normal_scale
  vec4 Emissive_Factor;          // rgb emissive color, w=unused
  float Spec_Exponent_Min;       // classic: min exponent (default 8)
  float Spec_Exponent_Max;       // classic: max exponent (default 96 Q3, 256 Source)
  float Fresnel_Min;             // classic: min Fresnel (default 0.02)
  float Fresnel_Max;             // classic: max Fresnel (default 0.12 Q3, 0.25 Source)
  float Env_Amount;              // classic: env reflection amount (default 0.10 Q3, 1.0 Source)
  float _pad1, _pad2, _pad3;
} GPU_Material; 

#define TEX_ABSENT 0xFFFFFFFFu

// Default classic material factors (Q3-style)
#define CLASSIC_DEFAULTS_Q3 \
  .Spec_Exponent_Min = 8.f,   .Spec_Exponent_Max = 96.f,  \
  .Fresnel_Min       = 0.02f, .Fresnel_Max       = 0.12f, \
  .Env_Amount        = 0.10f

// Default classic material factors (Source-style)
#define CLASSIC_DEFAULTS_SOURCE \
  .Spec_Exponent_Min = 8.f,   .Spec_Exponent_Max = 256.f, \
  .Fresnel_Min       = 0.02f, .Fresnel_Max       = 0.25f, \
  .Env_Amount        = 0.10f

// Scene lighting mode — replaces Env_Lightmap.w sentinel
typedef enum {
  SCENE_LIGHTING_BSP_LEGACY = 0, // lightmap + hemisphere ambient + sun
  SCENE_LIGHTING_IBL_ONLY   = 1, // IBL cubemap + sun (glTF scenes)
  SCENE_LIGHTING_MIXED      = 2  // both available (future)
} Scene_Lighting_Mode;

// Material factory: classic workflow with Q3-style defaults
inline GPU_Material Material_Classic_Q3 (float R, float G, float B) {
  return (GPU_Material){
    .Workflow = MATERIAL_WORKFLOW_CLASSIC,
    .Base_Tex = TEX_ABSENT, .Normal_Tex = TEX_ABSENT, .Spec_Tex = TEX_ABSENT,
    .Gloss_Tex = TEX_ABSENT, .EnvMask_Tex = TEX_ABSENT, .Rough_Tex = TEX_ABSENT,
    .Metal_Tex = TEX_ABSENT, .AO_Tex = TEX_ABSENT, .Emissive_Tex = TEX_ABSENT,
    .Base_Factor = {R, G, B, 1}, .Spec_Factor = {1, 1, 1, 0.3f},
    .PBR_Factor = {0.92f, 0.0f, 1.0f, 1.0f},
    CLASSIC_DEFAULTS_Q3};
}

// Material factory: classic workflow with Source-style defaults
inline GPU_Material Material_Classic_Source (float R, float G, float B) {
  return (GPU_Material){
    .Workflow     = MATERIAL_WORKFLOW_CLASSIC,
    .Base_Tex     = TEX_ABSENT,
    .Normal_Tex   = TEX_ABSENT,
    .Spec_Tex     = TEX_ABSENT,
    .Gloss_Tex    = TEX_ABSENT,
    .EnvMask_Tex  = TEX_ABSENT,
    .Rough_Tex    = TEX_ABSENT,
    .Metal_Tex    = TEX_ABSENT,
    .AO_Tex       = TEX_ABSENT,
    .Emissive_Tex = TEX_ABSENT,
    .Base_Factor  = {R, G, B, 1}, .Spec_Factor = {1, 1, 1, 0.15f},
    .PBR_Factor   = {0.95f, 0.0f, 1.0f, 1.0f},
    CLASSIC_DEFAULTS_SOURCE};
}

// Material factory: PBR metallic-roughness workflow (glTF)
inline GPU_Material Material_PBR (float R, float G, float B, float Roughness, float Metallic) {
  return (GPU_Material){
    .Workflow     = MATERIAL_WORKFLOW_PBR,
    .Base_Tex     = TEX_ABSENT,
    .Normal_Tex   = TEX_ABSENT,
    .Spec_Tex     = TEX_ABSENT,
    .Gloss_Tex    = TEX_ABSENT,
    .EnvMask_Tex  = TEX_ABSENT,
    .Rough_Tex    = TEX_ABSENT,
    .Metal_Tex    = TEX_ABSENT,
    .AO_Tex       = TEX_ABSENT,
    .Emissive_Tex = TEX_ABSENT,
    .Base_Factor  = {R, G, B, 1},
    .PBR_Factor   = {Roughness, Metallic, 1.0f, 1.0f}};
}

