  long           Length;
  long           Pos;
  uint           Bit_Buf;
  int            Bit_Count;
  int            Width, Height;
  int            Num_Components;
  int            Restart_Interval;
  int            QT[4][64];
  JPEG_Huffman   HT_DC[4], HT_AC[4];
