int           MDL_Read_File           (const char *Path, uint8_t **Out_Data, long *Out_Size, const MDL_Header **Out_Header);
void          MDL_Quat_To_Mat34       (float Qx, float Qy, float Qz, float Qw, vec3 Position, float Out_Matrix[3][4]);
