// Figure_Instance: the runtime representation of any loaded model — weapon viewmodel, player body, NPC, prop
typedef struct {
  Articulated_Figure     Figure;
  GPU_Buffer             Vertex_Buffer, Index_Buffer, Texture_Id_Buffer, Bottom_Level_Scratch;
  Acceleration_Structure Bottom_Level;
  Vertex                *Transformed_Vertices, *Current_Vertices;
  float                  Animation_Time;
  int                    Active_Animation;
  Animation_Blend_State  Blend;
  IK_State               IK;
  GPU_Buffer             IK_Buffer;
  GPU_IK_Instance        IK_Instance_CPU;     // CPU-side staging for GPU_IK_Instance upload
  int                    Is_Firing;
  float                  Fire_Time, Bob_Time;
  uint                   Texture_Base_Index;
  vec3                   GL_Origin;
  float                  GL_Yaw;
  GPU_Buffer             Bone_Buffer, Inv_Bind_Buffer, Bone_Parent_Buffer;
  GPU_Buffer             Bone_Weight_Buffer, Bone_Id_Buffer, Pose_Buffer;
  GPU_Buffer             Anim_Buffer;         // Animation bone-local library (all keyframes, uploaded once)
  GPU_Buffer             Bind_Vertex_Buffer;  // Read-only bind-pose vertices for GPU skinning input
  GPU_Buffer             Bone_World_Readback; // Host-visible: pre-InvBind bone world transforms (GPU writes, CPU reads)
  float                 *Bone_World_Mapped;   // Persistently mapped pointer into Bone_World_Readback
  uint8_t                Ray_Mask;
  float                  TLAS_Transform[3][4];
  int                    BLAS_Dirty;
  int                    Skinning_Pending;    // 1 = needs GPU skinning dispatch before BLAS rebuild
  uint                   Skinning_Frame_A, Skinning_Frame_B;
  float                  Skinning_Lerp;
  int                    Render_Instance_Slot; // Index into Render_Instance_Buffer (-1 = not assigned)

  // Locomotion state machine (Phase 4)
  int                    Locomotion_Sequences[LOCO_COUNT]; // Sequence indices per locomotion state
  Locomotion_State       Current_Loco_State;
  uint                   Upper_Body_Mask;                  // Bitmask: bones from Spine2 upward (Phase 7)

  // Ragdoll bridge
  int                    Ragdoll_Slot;                     // Index into GPU_Ragdoll_Pool (-1 = no ragdoll)
} Figure_Instance;

#define FIGURE_POOL_MAX 64
typedef struct { uint Index; uint Generation; } Figure_Handle;
#define FIGURE_HANDLE_NULL ((Figure_Handle){.Index = UINT32_MAX, .Generation = 0})

typedef struct {
  Figure_Instance Slots[FIGURE_POOL_MAX];
  uint            Generations[FIGURE_POOL_MAX];
  uint            Free_Stack[FIGURE_POOL_MAX];
  uint            Free_Count;
  uint            Active_Count;
  int             Active[FIGURE_POOL_MAX];
} Figure_Pool;

Figure_Handle Figure_Pool_Alloc (Figure_Pool *Pool, Figure_Instance **Out);
void          Figure_Pool_Free  (Figure_Pool *Pool, Figure_Handle Handle);

// ── Character: unified player/NPC entity ──────────────────────────────────────────────────────────────────────────────────────────────────────

typedef enum { CHARACTER_LOCAL, CHARACTER_REMOTE, CHARACTER_NPC } Character_Kind;

typedef struct {
  Character_Kind  Kind;
  int             Active;

  // Figure pool slot indices (into Figure_Pool.Slots[], -1 = unused)
  int             Body_Slot;       // Full mesh: shadow-only (local) or primary+shadow (remote)
  int             Legs_Slot;       // Lower-body filtered: primary-only (local only)
  int             Weapon_Slot;     // Held weapon: shadow-only (local) or primary+shadow (remote)
  int             Viewmodel_Slot;  // First-person weapon viewmodel (local only)

  // Attachment
  int             Weapon_Bone_Index;

  // World state (fed from physics or network)
  vec3            Position;
  float           Yaw;            // Radians
  float           Pitch;          // Radians
  vec3            Velocity;
  int             On_Ground;
} Character;

#define CHARACTER_MAX 16
Character Characters[CHARACTER_MAX];
uint      Character_Count = 0;

// Spawn a character into the pool. Returns character index, or -1 on failure.
int  Character_Spawn  (Character_Kind Kind, Figure_Pool *Pool, Scene *Scene_Data,
                       const char *Model_Path, const char *Weapon_Path,
                       vec3 Origin, float Yaw);

// Per-frame update: animation, TLAS placement, weapon bone attachment.
void Character_Update (Character *C, Figure_Pool *Pool, float Delta_Time);

// Serialises all IK chain data into a GPU storage buffer for consumption by the skinning compute shader. The buffer layout is:
//
// Floats 0– 3: [chain_count, enabled, padding, padding] (header) Floats 4–15: chain 0 data (type, bone_root, bone_mid, bone_end,
//                                  target_xyz, weight, angle_limit, enabled, pad, pad)
// Floats 16–27: chain 1 data ... and so on
//
// The buffer is reallocated if its current capacity is insufficient.
void IK_Upload (IK_State *IK, GPU_Buffer *IK_Buffer_Out);

// Updates the world-space target position and blend weight for one IK chain. Out-of-range chain indices are silently ignored.
void IK_Set_Target (IK_State *IK, int Chain_Index,
                    float Target_X, float Target_Y, float Target_Z, float Weight);

// Registers a new look-at IK chain (e.g. head tracking) and returns the chain index, or -1 if the chain table is full. The chain operates
// on a single end bone with no root or mid bone, constrained by the given angle limit in radians.
int IK_Add_Look_At (IK_State *IK, int Bone_End_Index, float Angle_Limit);

// Registers a new two-bone IK chain (e.g. arm or leg) and returns the chain index, or -1 if the chain table is full. The chain is enabled
// by default with full weight, a 180-degree joint angle limit, and a zero target position.
int IK_Add_Two_Bone (IK_State *IK, int Bone_Root_Index, int Bone_Mid_Index, int Bone_End_Index);

// Zeroes all fields in an IK_State, leaving it with no chains and IK disabled.
void IK_Initialize (IK_State *IK);

// Transitions the figure into ragdoll simulation. A snapshot of the current world-space bone pose is captured, all animation layers are
// faded out over Blend_Duration seconds, and the ragdoll blend timer is reset so the rendering layer can crossfade from the snapshot pose
// to the live physics pose.
void Animation_Blend_Begin_Ragdoll (Animation_Blend_State *Blend_State,
                                    const float World_Pose[][3][4],
                                    int Bone_Count, float Blend_Duration);

// Advances all active blend layers by Delta_Time seconds. For each layer: the playback cursor is advanced, looping or clamping at the
// sequence end; the fade-in weight ramp is updated if the layer is still blending in; and the fade-out weight ramp is updated if the layer
// is blending out, with the layer deactivated when the weight reaches zero. Also advances the ragdoll blend-out timer when a ragdoll is
// active. Returns 1 if any layer (or the ragdoll) is still active, 0 if all layers are idle.
int Animation_Blend_Tick (Animation_Blend_State *Blend_State,
                          const Articulated_Figure *Figure, float Delta_Time);

// Begins fading out the sequence on the given blend layer over Fade_Out_Duration seconds. A minimum fade duration of 0.001 s is enforced so
// weight never divides by zero. The layer is deactivated (Sequence_Index = -1) once the weight reaches zero during the next Tick call.
void Animation_Blend_Stop (Animation_Blend_State *Blend_State, int Layer_Index, float Fade_Out_Duration);

// Starts or restarts a sequence on the given blend layer. If Fade_In_Duration is greater than a small epsilon, the layer's weight begins at
// 0 and ramps to 1 over that duration; otherwise it snaps immediately to full weight.
void Animation_Blend_Play (Animation_Blend_State *Blend_State, int Layer_Index,
                           int Sequence_Index, float Fade_In_Duration, int Bone_Mask);

// Initialises an Animation_Blend_State to its default values. All layer sequence indices are set to -1 (inactive), and the ragdoll
// crossfade duration is seeded with the global default.
void Animation_Blend_Initialize (Animation_Blend_State *Blend_State);

// Spawns a GPU ragdoll from the entity's current skeleton pose. Returns the ragdoll slot index, or -1 on failure.
int Ragdoll_Spawn_From_Skeleton (Figure_Instance *Entity, float Floor_Y);

// Quaternion helpers for ragdoll body orientation
void Mat34_To_Quat_Row (const float *M, float Out[4]);
void Quat_Mul (const float A[4], const float B[4], float Out[4]);
void Quat_Conjugate (const float Q[4], float Out[4]);

// Movement_Style_Toggle declared after Player typedef (see below)

// Composes two tag transforms A and B into C, producing the world-space transform that results from placing B's local frame inside A's
// local frame. Both input transforms and the output are flat 12-float arrays laid out as: [origin_xyz | col0_xyz | col1_xyz | col2_xyz]
// where col0/col1/col2 are the three columns of the 3×3 rotation matrix R.
//
// The composition is: C.origin = R_A * B.origin + A.origin
//                     C.axis_j = R_A * B.axis_j  (for each of the three column vectors)
void Tag_Compose (const float *Transform_A, const float *Transform_B, float *Transform_C);

// Searches the tag array for the named tag at the specified animation frame and copies its origin and 3×3 axis matrix into a flat 12-float
// array laid out as [origin_xyz | row0_xyz | row1_xyz | row2_xyz]. Returns 1 if the tag was found, or 0 if no tag with the given name
// exists in the frame's tag block.
int MD3_Find_Tag_At_Frame (const uint8_t *File_Data, int Tag_Count, int Tags_Offset,
                           int Frame_Index, const char *Tag_Name, float Out_Transform[12]);

