// Packing routine - fp16 RLE packing for push constants
uint16_t Float_To_Half (float Value) {
  uint Bits; memcpy (&Bits, &Value, 4);
  uint Sign =  (Bits >> 16) & 0x8000;
  int  Exp  = ((Bits >> 23) & 0xFF) - 127 + 15;
  uint Mant =  (Bits >> 13) & 0x03FF;
  if (Exp <= 0)  return (uint16_t)Sign;            // Underflow > ~Zero
  if (Exp >= 31) return (uint16_t)(Sign | 0x7C00); // Overflow  > ~Infinity
  return (uint16_t)(Sign | ((uint)Exp << 10) | Mant);
}
uint Pack_Half2x16 (float A, float B) {
  return (uint)Float_To_Half (A) | ((uint)Float_To_Half (B) << 16);
}
void Pack_Mat4_Half (const mat4 *M, uint Out[8]) {
  for (int I = 0; I < 8; I++)
    Out[I] = Pack_Half2x16 (M->m[I * 2], M->m[I * 2 + 1]);
}

